import json

async def execute(self, inputs):
    from src.runtime.assets.assembly import get_environment_builder

    environment = str(inputs.get('environment') or self.parameters.get('environment', 'industrial_hangar') or 'industrial_hangar')
    recs_json   = str(inputs.get('recommendations_json') or '')

    recommendations = None
    if recs_json.strip():
        try:
            recommendations = json.loads(recs_json)
            if not isinstance(recommendations, list):
                recommendations = None
        except Exception:
            recommendations = None

    try:
        builder = get_environment_builder()
        plan    = builder.build_environment(environment, recommendations)

        plan_dict = plan.to_dict()
        self.log_info(
            f'[EnvironmentBuilder] {environment!r}: '
            f'{len(plan.zones)} zones, {plan.asset_count} assets, ok={plan.ok}'
        )
        if plan.warnings:
            for w in plan.warnings:
                self.log_warning(f'[EnvironmentBuilder] {w}')

        return {
            'environment_plan_json': json.dumps(plan_dict),
            'plan_id':    plan.plan_id,
            'zone_count': len(plan.zones),
            'asset_count': plan.asset_count,
            'has_hero_zone': plan.has_hero_zone,
            'ok':         plan.ok,
            'exec_out':   True,
        }
    except Exception as e:
        self.log_error(f'[EnvironmentBuilder] {e}')
        return {
            'environment_plan_json': json.dumps({'ok': False, 'errors': [str(e)]}),
            'plan_id': '',
            'zone_count': 0,
            'asset_count': 0,
            'has_hero_zone': False,
            'ok': False,
            'exec_out': True,
        }

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Environment_Builder(BaseNode):
        name = 'hou_mcp_environment_builder'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Environment_Builder
